-- B2c: two notification types (the other participant's account was locked;
-- rider access changed) and an index for the Notifications page, newest first.
-- AlterTable
ALTER TABLE `notifications` MODIFY `type` ENUM('REQUEST_ACCEPTED', 'SEAT_BOOKED', 'CARPOOL_BOOKING_REQUESTED', 'CARPOOL_BOOKING_ACCEPTED', 'CARPOOL_BOOKING_REJECTED', 'CARPOOL_CONTRACT_CREATED', 'CARPOOL_SESSION_REMINDER', 'ACTIVITY_REMINDER', 'COMPLETION_REQUESTED', 'AUTO_COMPLETED', 'AUTO_CLOSED_NOT_MARKED', 'ACTIVITY_CANCELLED', 'DISPUTE_OPENED', 'DISPUTE_UPDATED', 'DISPUTE_RESOLVED', 'NEW_CHAT_MESSAGE', 'SUB_AREA_NEW_REQUEST', 'STUDENT_VERIFICATION_RESULT', 'RIDER_VERIFICATION_RESULT', 'REQUEST_EXPIRED', 'CARPOOL_PAYMENT_DUE', 'REPORT_UPDATE', 'SUPPORT_UPDATE', 'ANNOUNCEMENT', 'ACCOUNT_STATUS_CHANGED', 'PASSWORD_RESET_REQUESTED', 'PASSWORD_CHANGED', 'LICENCE_EXPIRY_REMINDER', 'PARTICIPANT_ACCOUNT_LOCKED', 'RIDER_ACCESS_CHANGED') NOT NULL;

-- CreateIndex
CREATE INDEX `notifications_user_id_channel_created_at_idx` ON `notifications`(`user_id`, `channel`, `created_at`);
